import { useState, FormEvent } from 'react';
import {
  JxCard,
  JxFormField,
  JxInput,
  JxHelperText,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxAlert,
  JxStack,
} from '@jinx-ui/react';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Role = 'member' | 'admin' | 'viewer';

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_RE.test(email);
  const showError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-4)">
      {submitted && (
        <JxAlert variant="success" onDismiss={() => setSubmitted(false)}>
          Приглашение отправлено
        </JxAlert>
      )}

      <JxCard>
        <form onSubmit={handleSubmit}>
          <JxStack direction="column" gap="var(--jx-space-4)">
            <JxFormField>
              <label htmlFor="invite-email">Почта</label>
              <JxInput
                id="invite-email"
                type="email"
                value={email}
                onChange={(e: { target: { value: string } }) => setEmail(e.target.value)}
                onBlur={() => setTouched(true)}
                invalid={showError}
                placeholder="name@company.com"
              />
              {showError ? (
                <JxHelperText variant="error">
                  Введите корректный адрес электронной почты
                </JxHelperText>
              ) : (
                <JxHelperText>На эту почту придёт приглашение в команду</JxHelperText>
              )}
            </JxFormField>

            <JxFormField>
              <label htmlFor="invite-role">Роль</label>
              <JxSelect
                id="invite-role"
                value={role}
                onChange={(value: Role) => setRole(value)}
              >
                <JxSelectOption value="member">Участник</JxSelectOption>
                <JxSelectOption value="admin">Администратор</JxSelectOption>
                <JxSelectOption value="viewer">Наблюдатель</JxSelectOption>
              </JxSelect>
            </JxFormField>

            <JxSwitch
              checked={notify}
              onChange={(checked: boolean) => setNotify(checked)}
              label="Отправить уведомление"
            />

            <JxButton type="submit" disabled={!canSubmit}>
              Отправить приглашение
            </JxButton>
          </JxStack>
        </form>
      </JxCard>
    </JxStack>
  );
}

